"""Application FastAPI de l'UI web : pages statiques, vues JSON des écrans (AD-25, Stories 7.13-7.14).

Seul module qui crée l'application. Il ne reçoit ses services que de `ui/cli.py`, racine de
composition (AD-1) : la lecture du manifeste du Passage affiché, `lire_manifeste(repli)`, et sa
lecture complète, `lire_consultation(repli)`. Chaque écran est une page HTML de `statique/`, sans
moteur de gabarits ; le script `cadre.js` charge `/api/cadre`, `carte.js` et `detail.js`
chargent `/api/carte` et `/api/entites/{entite}`. `GET /livrables/{nom}` sert le Rapport
quotidien et le Comité de pilotage du Passage affiché : le serveur ne construit aucun chemin de
Passage, il lit `Consultation.livrable` (AD-11). Polices, CSS et scripts sont servis ici :
aucune requête ne sort (NFR-12). Le serveur n'écoute que `127.0.0.1` (voir `cli`).

Le mode vit dans le processus serveur et ne change jamais seul (AD-19) : il est fixé au
démarrage par `USINE_MODE_REPLI`.
"""

import html
from collections.abc import Callable
from pathlib import Path, PurePosixPath
from typing import Literal, cast

from fastapi import FastAPI
from fastapi.responses import FileResponse, HTMLResponse, RedirectResponse, Response
from fastapi.staticfiles import StaticFiles

from usine.contrats.erreurs import UsineErreur
from usine.contrats.passage import ManifestePassage, chemin_fichier_passage
from usine.ui.carte import (
    AUCUN_PASSAGE,
    MIME_LIVRABLES,
    LectureVueCarte,
    entites_triees,
    vue_carte,
)
from usine.ui.detail import LectureDetail, Palier, entite_absente, vue_detail
from usine.ui.vues import VueCadre, VueCarte, VueDetail, vue_cadre

REPERTOIRE_STATIQUE = Path(__file__).resolve().with_name("statique")
"""Pages HTML, feuille de style, scripts et polices servis en local."""

HOTE = "127.0.0.1"
"""Seule adresse d'écoute : l'interface n'est jamais joignable depuis le réseau (AD-25)."""

PAGES: dict[str, str] = {
    "/": "carte-meteo.html",
    "/entites/{entite}": "detail-entite.html",
    "/chaine": "chaine.html",
    "/agent": "agent.html",
    "/avant-apres": "avant-apres.html",
    "/pseudonymisation": "pseudonymisation.html",
    "/outillage": "outillage.html",
}
"""Route de chaque écran (EXPERIENCE.md, Information Architecture) et sa page statique."""

LireManifeste = Callable[[bool], ManifestePassage | None]
"""Manifeste du Passage affiché dans le mode donné (`True` : Mode repli), `None` s'il n'y en a pas ;
lève `UsineErreur` (ou `OSError`) si la lecture est impossible."""


class LectureEcrans(LectureVueCarte, LectureDetail):
    """Lectures de la `Consultation` dont les écrans ont besoin (carte, détail, livrables)."""


LireConsultation = Callable[[bool], LectureEcrans | None]
"""Lecture du Passage affiché dans le mode donné, `None` s'il n'y en a pas ; mêmes erreurs."""

_LIBELLE_ERREUR_LECTURE = "Lecture du Passage impossible : "


def _message(exc: UsineErreur | OSError) -> str:
    if isinstance(exc, UsineErreur):
        return str(exc)
    return f"{_LIBELLE_ERREUR_LECTURE}{exc}"


def _page_html(titre: str, corps: str, statut: int) -> HTMLResponse:
    contenu = (
        '<!doctype html><html lang="fr"><head><meta charset="utf-8">'
        f"<title>{html.escape(titre)} · Usine de migration</title>"
        '<link rel="icon" href="data:,"><link rel="stylesheet" href="/statique/cadre.css">'
        '</head><body><main class="contenu">'
        f'<h1>{html.escape(titre)}</h1><p>{corps}</p>'
        '<p><a href="/">Retour à la carte météo</a></p></main></body></html>'
    )
    return HTMLResponse(contenu, status_code=statut)


def creer_application(
    *,
    repli: bool,
    lire_manifeste: LireManifeste | None = None,
    lire_consultation: LireConsultation | None = None,
) -> FastAPI:
    """Application des sept écrans ; `repli` est le mode imposé au démarrage (AD-19).

    Sans `lire_manifeste`, le cadre lit le manifeste de `lire_consultation` ; sans
    `lire_consultation`, les écrans n'ont aucun Passage à afficher.
    """
    application = FastAPI(
        title="Usine de migration", docs_url=None, redoc_url=None, openapi_url=None
    )
    application.mount("/statique", StaticFiles(directory=REPERTOIRE_STATIQUE), name="statique")

    def lire_ecrans() -> LectureEcrans | None:
        return None if lire_consultation is None else lire_consultation(repli)

    def manifeste_affiche() -> ManifestePassage | None:
        if lire_manifeste is not None:
            return lire_manifeste(repli)
        lecture = lire_ecrans()
        return None if lecture is None else lecture.manifeste()

    def cadre() -> VueCadre:
        try:
            return vue_cadre(repli=repli, manifeste=manifeste_affiche(), erreur=None)
        except UsineErreur as exc:
            return vue_cadre(repli=repli, manifeste=None, erreur=str(exc))
        except OSError as exc:  # répertoire illisible : bandeau d'erreur, pas une 500
            return vue_cadre(repli=repli, manifeste=None, erreur=_message(exc))

    def carte() -> VueCarte:
        try:
            return vue_carte(lire_ecrans())
        except (UsineErreur, OSError) as exc:
            return vue_carte(None).model_copy(
                update={"message": None, "lien_chaine": False, "erreur": _message(exc)}
            )

    def detail(entite: str, palier: str = "2") -> VueDetail:
        choix: Palier = 1 if palier == "1" else 2  # illisible : Palier 2
        try:
            lecture = lire_ecrans()
            if lecture is None:
                return VueDetail(entite=entite, absente=AUCUN_PASSAGE)
            return vue_detail(lecture, entite, choix)
        except (UsineErreur, OSError) as exc:
            return VueDetail(entite=entite, absente=None, erreur=_message(exc))

    def entites() -> RedirectResponse:
        try:
            lecture = lire_ecrans()
            meteos = entites_triees(lecture.meteo()) if lecture is not None else []
        except (UsineErreur, OSError):
            meteos = []
        cible = f"/entites/{meteos[0].entite}" if meteos else "/"
        return RedirectResponse(cible, status_code=307)

    def livrable(nom: str) -> Response:
        if nom not in MIME_LIVRABLES:
            return _page_html("Livrable inconnu", html.escape(nom), 404)
        cle = cast(Literal["rapport_xlsx", "rapport_pptx"], nom)
        try:
            lecture = lire_ecrans()
            if lecture is None:
                return _page_html("Livrable absent", AUCUN_PASSAGE, 404)
            nom_fichier = PurePosixPath(
                chemin_fichier_passage(cle, lecture.manifeste().date_arrete)
            ).name
            contenu = lecture.livrable(cle)
        except (UsineErreur, OSError) as exc:
            return _page_html("Lecture impossible", html.escape(_message(exc)), 500)
        if contenu is None:
            corps = f"{html.escape(nom_fichier)} : non généré pour ce Passage."
            return _page_html("Livrable non généré", corps, 404)
        return Response(
            contenu,
            media_type=MIME_LIVRABLES[nom],
            headers={"Content-Disposition": f'attachment; filename="{nom_fichier}"'},
        )

    application.add_api_route("/api/cadre", cadre, response_model=VueCadre)
    application.add_api_route("/api/carte", carte, response_model=VueCarte)
    application.add_api_route("/api/entites/{entite}", detail, response_model=VueDetail)
    application.add_api_route("/entites", entites, include_in_schema=False)
    application.add_api_route(
        "/livrables/{nom}", livrable, methods=["GET", "HEAD"], include_in_schema=False
    )

    for route, fichier in PAGES.items():
        application.add_api_route(
            route, _page(REPERTOIRE_STATIQUE / fichier), include_in_schema=False
        )
    return application


def _page(chemin: Path) -> Callable[..., FileResponse]:
    def servir() -> FileResponse:
        return FileResponse(chemin, media_type="text/html; charset=utf-8")

    return servir


_ = entite_absente  # message partagé avec `vue_detail`
PYEOF
